app.MapGet("/products", async ([AsParameters] ListQuery q, AppDbContext db, CancellationToken ct) =>
{
    var page = Math.Max(1, q.Page ?? 1);
    var pageSize = Math.Clamp(q.PageSize ?? 20, 1, 100);

    IQueryable<Product> query = db.Products.AsNoTracking();
    if (!string.IsNullOrWhiteSpace(q.Search)) query = query.Where(p => p.Name.Contains(q.Search.Trim()));
    if (!string.IsNullOrWhiteSpace(q.Category)) query = query.Where(p => p.Category == q.Category.Trim());

    query = ApplySort(query, q.Sort);                       // allowlist, ends with ThenBy(p => p.Id)

    var total = await query.CountAsync(ct);
    var items = await query.Skip((page - 1) * pageSize).Take(pageSize)
        .Select(p => new ProductListItem(p.Id, p.Name, p.Price))
        .ToListAsync(ct);

    return Results.Ok(new PagedResult<ProductListItem>(items, page, pageSize, total));
});

static IQueryable<Product> ApplySort(IQueryable<Product> query, string? sort) =>
    (sort ?? "").Trim().ToLowerInvariant() switch
    {
        "price"    => query.OrderBy(p => p.Price).ThenBy(p => p.Id),
        "-price"   => query.OrderByDescending(p => p.Price).ThenBy(p => p.Id),
        "created"  => query.OrderBy(p => p.CreatedAt).ThenBy(p => p.Id),
        "-created" => query.OrderByDescending(p => p.CreatedAt).ThenBy(p => p.Id),
        "-name"    => query.OrderByDescending(p => p.Name).ThenBy(p => p.Id),
        _          => query.OrderBy(p => p.Name).ThenBy(p => p.Id),
    };
